// usage: node summarize.js <prefix>   e.g. before / after
const fs = require('fs'), dir = __dirname, pre = process.argv[2]
const runs = [1, 2, 3].map(i => JSON.parse(fs.readFileSync(`${dir}/${pre}-${i}.json`)))
const med = a => [...a].sort((x, y) => x - y)[1]
const m = [['perf', r => r.categories.performance.score * 100], ['FCP ms', r => r.audits['first-contentful-paint'].numericValue],
  ['LCP ms', r => r.audits['largest-contentful-paint'].numericValue], ['TBT ms', r => r.audits['total-blocking-time'].numericValue],
  ['CLS', r => r.audits['cumulative-layout-shift'].numericValue], ['SI ms', r => r.audits['speed-index'].numericValue],
  ['transfer KB', r => r.audits['total-byte-weight'].numericValue / 1024]]
console.log(runs[0].lighthouseVersion, runs[0].configSettings.formFactor, runs[0].environment.hostUserAgent)
for (const [n, f] of m) { const v = runs.map(f); console.log(n.padEnd(12), v.map(x => x.toFixed(2)).join(' | '), ' median', med(v).toFixed(2)) }

