// Ledgerboard: marketing page + dashboard stats for local performance testing. No dependencies.
// Start: node server.js   (http://127.0.0.1:3200)   First run: node make_assets.js
const http = require('http'), fs = require('fs'), path = require('path'), zlib = require('zlib')
const sleep = ms => new Promise(r => setTimeout(r, ms))
async function query(sql) { await sleep(30); return { sql, rows: 1 } }   // stands in for a DB round trip

// Static files are read once and gzip/ETag variants are cached in memory (public/ is small and static).
const cache = new Map()
async function loadStatic(f) {
  const p = path.join(__dirname, 'public', f)
  const st = await fs.promises.stat(p).catch(() => null)
  if (!st || !st.isFile()) return null
  const hit = cache.get(f)
  if (hit && hit.mtime === st.mtimeMs) return hit
  const body = await fs.promises.readFile(p)
  const compressible = /\.(js|css|html|svg)$/.test(f)
  const entry = { mtime: st.mtimeMs, body, gzip: compressible ? zlib.gzipSync(body, { level: 9 }) : null,
    etag: `"${st.size}-${Math.round(st.mtimeMs)}"` }
  cache.set(f, entry); return entry
}
const types = { '.png': 'image/png', '.webp': 'image/webp', '.js': 'text/javascript', '.css': 'text/css', '.html': 'text/html' }

http.createServer(async (req, res) => {
  if (req.url === '/api/stats') {
    // One round trip per query, but independent queries run concurrently instead of 31 sequential awaits.
    // (With a real DB this should be a single grouped query: select customer_id, sum(total) ... group by customer_id.)
    const [customers, ...out] = await Promise.all([query('select id from customers limit 30'),
      ...Array.from({ length: 30 }, (_, i) => query(`select sum(total) from invoices where customer_id=${i}`))])
    res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' })   // stats stay uncached
    return res.end(JSON.stringify({ customers: 30, totals: out.length }))
  }
  const f = req.url === '/' ? 'index.html' : path.basename(req.url.split('?')[0])
  const e = await loadStatic(f)
  if (!e) { res.writeHead(404); return res.end() }
  // Images are static assets (safe to cache for a day); html/js/css revalidate via ETag so deploys show up immediately.
  const immutableish = /\.(png|webp)$/.test(f)
  const headers = { 'Content-Type': types[path.extname(f)] || 'application/octet-stream', ETag: e.etag,
    'Cache-Control': immutableish ? 'public, max-age=86400' : 'no-cache', Vary: 'Accept-Encoding' }
  if (req.headers['if-none-match'] === e.etag) { res.writeHead(304, headers); return res.end() }
  const gz = e.gzip && /\bgzip\b/.test(req.headers['accept-encoding'] || '')
  if (gz) headers['Content-Encoding'] = 'gzip'
  res.writeHead(200, headers)
  res.end(gz ? e.gzip : e.body)
}).listen(3200, '127.0.0.1', () => console.log('Ledgerboard on http://127.0.0.1:3200'))

